// Rules for any password a person chooses (temporary passwords generated by
// the server are random and skip this). One place, so every path that sets a
// password applies the same rules and messages.
const fs = require('fs');
const path = require('path');
const bcrypt = require('bcrypt');

// Cost for every new bcrypt hash. Older, cheaper hashes are upgraded on the
// next successful sign-in (authService.login).
const BCRYPT_COST = 12;

const MIN_LENGTH = 10;
const MAX_LENGTH = 128;
const COMMON_PASSWORDS_FILE = path.join(__dirname, '../data/common-passwords.txt');

// Used only if data/common-passwords.txt is missing or unreadable, so a
// broken deploy weakens the check instead of failing every password change.
const FALLBACK_COMMON_PASSWORDS = [
  '123456', '1234567', '12345678', '123456789', '1234567890', '12345', '1234', '111111', '000000',
  'password', 'passw0rd', 'password1', 'qwerty', 'qwertyuiop', 'qwerty123', 'abc123', 'letmein',
  'welcome', 'admin', 'administrator', 'iloveyou', 'monkey', 'dragon', 'football', 'baseball',
  'sunshine', 'princess', 'master', 'login', 'starwars', 'whatever', 'trustno1', 'superman',
  'shadow', 'michael', 'charlie', 'freedom', 'changeme', 'secret', 'india', 'asdfghjkl', 'zxcvbnm',
];

const parseList = (text) => new Set(
  text.split('\n')
    .map((line) => line.trim().toLowerCase())
    .filter((line) => line && !line.startsWith('#'))
);

// Loaded once, when this module is first required (at startup).
const loadCommonPasswords = (file = COMMON_PASSWORDS_FILE, readFile = fs.readFileSync) => {
  try {
    return parseList(readFile(file, 'utf8'));
  } catch (err) {
    // eslint-disable-next-line global-require
    require('../logger').error(
      { err: { message: err.message, code: err.code } },
      `[password policy] Could not read the common-password list (${file}); using a short built-in list instead`,
    );
    return new Set(FALLBACK_COMMON_PASSWORDS);
  }
};

const commonPasswords = loadCommonPasswords();

// Trailing ASCII digits, punctuation and whitespace: "Sunshine2026!" ->
// "sunshine". Letters in any script are kept.
const TRAILING_SUFFIX = /[0-9!-/:-@[-`{-~\s]+$/;

const isCommonPassword = (password, list = commonPasswords) => {
  const lower = password.toLowerCase();
  if (list.has(lower)) return true;
  // "Sunshine2026!" is still "sunshine" with a suffix.
  const base = lower.replace(TRAILING_SUFFIX, '');
  return base.length >= 4 && base !== lower && list.has(base);
};

// Words of four or more letters/digits from the email's local part and the
// person's name: "ravi.kumar@x.com", "Ravi Kumar" -> ["ravi", "kumar"].
const personalWords = ({ email, name } = {}) => {
  const localPart = String(email || '').split('@')[0];
  return [...new Set(
    `${localPart} ${name || ''}`.toLowerCase().split(/[^a-z0-9]+/).filter((word) => word.length >= 4)
  )];
};

// Returns the problem with the password as a message, or null if it is fine.
const getPasswordProblem = (password, person = {}) => {
  if (typeof password !== 'string' || password.length === 0) return 'Enter a new password.';
  if (password.length < MIN_LENGTH) return `The new password must be at least ${MIN_LENGTH} characters long.`;
  if (password.length > MAX_LENGTH) return `The new password must be at most ${MAX_LENGTH} characters long.`;
  if (new Set(password).size === 1) return 'The new password cannot be one character repeated.';
  if (isCommonPassword(password)) return 'This password is too common and easy to guess. Choose something less predictable.';
  const lower = password.toLowerCase();
  if (personalWords(person).some((word) => lower.includes(word))) {
    return 'The new password must not contain your name or email address.';
  }
  return null;
};

const assertValidPassword = (password, person) => {
  const problem = getPasswordProblem(password, person);
  if (problem) {
    const err = new Error(problem);
    err.statusCode = 400;
    throw err;
  }
};

const hashPassword = (password) => bcrypt.hash(password, BCRYPT_COST);

module.exports = {
  BCRYPT_COST,
  MIN_LENGTH,
  MAX_LENGTH,
  getPasswordProblem,
  assertValidPassword,
  isCommonPassword,
  loadCommonPasswords,
  hashPassword,
};
